#!/usr/bin/env node
//
// tools/visual/gen-block-font.mjs — emit the per-platform embedded constants
// for the harness-label block font from the canonical atlas
// (tools/visual/block-font.json).
//
// Why codegen instead of runtime file reads: the natives must not read repo
// files at render time (bundles are sealed), and hand-copying bit patterns
// across three languages is exactly how the copies would drift. Each
// generated file embeds the same rows as integers plus the ATLAS CHECKSUM;
// per-platform pin tests recompute the checksum from the embedded data and
// compare against this file's, so any drift (or hand-edit of a generated
// file) fails loudly.
//
// Deterministic output: glyphs sorted by codepoint, rows as decimal ints
// (bit 4 = leftmost column), LF newlines — regenerating byte-identically.
//
// Usage: node tools/visual/gen-block-font.mjs

import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const atlas = JSON.parse(readFileSync(join(REPO, 'tools/visual/block-font.json'), 'utf8'));

// Canonical serialization for the checksum: char:rowInts joined — the SAME
// string every platform's pin test rebuilds from its embedded constants.
const chars = Object.keys(atlas.glyphs).sort((a, b) => a.charCodeAt(0) - b.charCodeAt(0));
const rowInts = (ch) => atlas.glyphs[ch].map((r) => parseInt(r, 2));
const canonical = chars.map((c) => `${c.charCodeAt(0)}:${rowInts(c).join(',')}`).join(';')
  + `|${atlas.cell.width}x${atlas.cell.height}|adv${atlas.advance}|lh${atlas.lineHeight}`;
const checksum = createHash('sha256').update(canonical).digest('hex').slice(0, 16);

const header = (lang) => `${lang} GENERATED by tools/visual/gen-block-font.mjs from tools/visual/block-font.json — DO NOT EDIT.
${lang} The harness-label block font: 5x7 bit patterns drawn as integer-coordinate
${lang} filled rects, so placeholder labels rasterize PIXEL-IDENTICALLY on all three
${lang} platforms (no font stack — the fix for the cross-platform glyph wall that
${lang} capped ~50 text-bearing fixtures at SSIM 0.90-0.949). Row ints: bit 4 is the
${lang} LEFTMOST column of the 5-wide cell. Checksum pins the atlas: ${checksum}`;

// ── TypeScript (web) ─────────────────────────────────────────────────────────
{
  const lines = chars.map((c) => `  ${JSON.stringify(c)}: [${rowInts(c).join(', ')}],`);
  writeFileSync(join(REPO, 'runtimes/web/src/renderer/BlockFont.gen.ts'),
`${header('//')}

export const BLOCK_FONT_CELL_W = ${atlas.cell.width};
export const BLOCK_FONT_CELL_H = ${atlas.cell.height};
export const BLOCK_FONT_ADVANCE = ${atlas.advance};
export const BLOCK_FONT_LINE_HEIGHT = ${atlas.lineHeight};
export const BLOCK_FONT_CHECKSUM = ${JSON.stringify(checksum)};
export const BLOCK_FONT_GLYPHS: Record<string, number[]> = {
${lines.join('\n')}
};
`);
}

// ── Kotlin (compose) ─────────────────────────────────────────────────────────
{
  const entries = chars.map((c) => `        '${c === "'" ? "\\'" : c === '\\' ? '\\\\' : c}' to intArrayOf(${rowInts(c).join(', ')}),`);
  writeFileSync(join(REPO, 'runtimes/compose/src/main/java/com/styleconverter/runtime/core/renderer/BlockFont.gen.kt'),
`${header('//')}
package com.styleconverter.runtime.core.renderer

internal object BlockFont {
    const val CELL_W = ${atlas.cell.width}
    const val CELL_H = ${atlas.cell.height}
    const val ADVANCE = ${atlas.advance}
    const val LINE_HEIGHT = ${atlas.lineHeight}
    const val CHECKSUM = "${checksum}"
    val GLYPHS: Map<Char, IntArray> = mapOf(
${entries.join('\n')}
    )
}
`);
}

// ── Swift (swiftui) ──────────────────────────────────────────────────────────
{
  const entries = chars.map((c) => `        ${JSON.stringify(c)}: [${rowInts(c).join(', ')}],`);
  writeFileSync(join(REPO, 'runtimes/swiftui/Sources/StyleConverterRuntime/Renderer/BlockFont.gen.swift'),
`${header('//')}

enum BlockFont {
    static let cellW = ${atlas.cell.width}
    static let cellH = ${atlas.cell.height}
    static let advance = ${atlas.advance}
    static let lineHeight = ${atlas.lineHeight}
    static let checksum = "${checksum}"
    static let glyphs: [Character: [Int]] = [
${entries.join('\n')}
    ]
}
`);
}

console.log(`block-font: ${chars.length} glyphs → 3 generated files (checksum ${checksum})`);
